# =====================================================================
#   CS2 на pygame — de_mirage  (ВЕБ-ВЕРСИЯ ДЛЯ САЙТА)
#
#   Это маленький загрузчик. Он сразу показывает экран загрузки
#   (что грузится и сколько секунд), а потом распаковывает и запускает
#   код игры — он лежит внизу файла в сжатом виде.
#   Полный читаемый код игры — в файле cs2_pygame.py.
#   Код игры: 15032 строк, 703 КБ (в сжатом виде 244 КБ).
# =====================================================================
import sys
import time
import json
import asyncio
import base64
import zlib
import traceback
import os
os.environ.setdefault('SDL_MOUSE_RELATIVE_SCALING', '0')
import pygame

BOOT_T0 = time.perf_counter()
W, H = 960, 540
try:
    pygame.mixer.pre_init(22050, -16, 1, 512)
except Exception:
    pass
pygame.init()
screen = pygame.display.set_mode((W, H))
pygame.display.set_caption('CS2 — загрузка')
STAGES = []          # [название, состояние, секунды]
NOTES = []
GAME_NS = {}
_fonts = {}


def _imports_for_site():
    """Не вызывается: по этому списку сайт заранее подгружает те же модули, что нужны игре."""
    import math, random, array, collections, threading, socket, hashlib, re, shutil, subprocess, atexit
    import platform
    import js


def _text(t, n, col, pos, anchor='topleft'):
    f = _fonts.get(n)
    if f is None:
        f = _fonts[n] = pygame.font.Font(None, n)
    s = f.render(t, True, col)
    r = s.get_rect(**{anchor: pos})
    screen.blit(s, r)


def _page_seconds():
    """Сколько секунд прошло с открытия страницы — столько сайт загружал Python и pygame."""
    try:
        import platform
        w = getattr(platform, 'window', None)
        if w is None:
            import js as w
        return float(w.performance.now()) / 1000.0
    except Exception:
        return None


def _draw():
    screen.fill((18, 16, 14))
    _text('CS2', 110, (255, 190, 70), (W // 2, 92), 'center')
    _text('de_mirage', 32, (255, 255, 255), (W // 2, 150), 'center')
    done = sum(1 for s in STAGES if s[1] == 'done')
    screen.fill((50, 50, 50), (W // 2 - 300, 182, 600, 12))
    screen.fill((255, 190, 70), (W // 2 - 300, 182, int(600 * done / 6.0), 12))
    y = 212
    for name, st, sec in STAGES:
        col = {'done': (110, 230, 120), 'run': (255, 205, 90), 'err': (235, 60, 50)}.get(st, (150, 150, 150))
        mark = {'done': 'готово', 'run': 'идёт...', 'err': 'ОШИБКА'}.get(st, 'ждёт')
        _text(name, 26, col, (W // 2 - 300, y))
        _text(mark + ('   %.1f с' % sec if sec is not None else ''), 26, col, (W // 2 + 300, y), 'topright')
        y += 30
    y += 6
    for ln in NOTES[-9:]:
        _text(ln[:110], 20, (230, 200, 160), (W // 2 - 300, y))
        y += 20
    _text('Прошло с запуска кода: %.1f с' % (time.perf_counter() - BOOT_T0), 22, (170, 170, 170),
          (W // 2, H - 26), 'center')
    pygame.display.flip()


async def _show():
    for _ in pygame.event.get():
        pass
    _draw()
    await asyncio.sleep(0.02)          # даём браузеру нарисовать кадр


async def _stage(name, fn):
    STAGES.append([name, 'run', None])
    await _show()
    t = time.perf_counter()
    res = fn()
    STAGES[-1][1:] = ['done', time.perf_counter() - t]
    print('[CS2] %s — %.2f с' % (name, STAGES[-1][2]))
    return res


async def _boot():
    try:
        ps = _page_seconds()
        STAGES.append(['Сайт загрузил Python и pygame', 'done', ps])
        tr, pr = sys.gettrace(), sys.getprofile()
        if tr is not None or pr is not None:
            NOTES.append('Сайт включил пошаговую отладку — она замедляет игру в десятки раз.')
            NOTES.append('Для игры отладка выключена (кнопки «шаг» сайта на игру не действуют).')
        await _show()
        src = await _stage('Распаковка кода игры (703 КБ)',
                           lambda: zlib.decompress(base64.b64decode(''.join(PAYLOAD.split()))).decode('utf-8'))
        code = await _stage('Компиляция кода (15032 строк)', lambda: compile(src, 'cs2_pygame.py', 'exec'))
        g = GAME_NS
        g.update({'__name__': '__cs2__', '__file__': globals().get('__file__', 'cs2_pygame.py')})
        if tr is not None or pr is not None:
            sys.settrace(None)
            sys.setprofile(None)
        await _stage('Подготовка игры', lambda: exec(code, g))
        STAGES.append(['Запуск: карта, звук, меню', 'run', None])
        await _show()
        print('[CS2] загрузчик: всего %.2f с, дальше — игра' % (time.perf_counter() - BOOT_T0))
    except Exception:
        err = traceback.format_exc()
        print(err)
        for s in STAGES:
            if s[1] == 'run':
                s[1] = 'err'
        NOTES.extend(err.strip().splitlines()[-8:])
        while True:                      # показываем ошибку, а не белый экран
            await _show()
            await asyncio.sleep(0.2)
    await g['main']()


def _start():
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = None
    if loop is not None:
        loop.create_task(_boot())
    else:
        asyncio.run(_boot())


